#pragma once
namespace save_transfer_cases {
static void registry(const fs::path& path,const std::string& value){mahoyo::save::Document doc;doc.hostExtra.assign(value.begin(),value.end());mahoyo::save::writeAtomic(path,doc);}
static void refresh(){
    Program p;for(auto pair:std::vector<std::pair<int,int>>{{5,17},{1<<5,26},{3,8},{100,9}}){p.push(pair.first);p.push(pair.second);p.op(0xe2);}p.push(1);p.push(9);p.op(0xe6);p.dialogue(0);p.op(0xf4);
    Fixture f(std::move(p));f.command("textSpeed","0");f.firstComplete();auto rejected=f.command("backupPrepare");check(rejected.find("Save transfer preparation failed.")!=std::string::npos&&rejected.find("\"error\":\"\"")!=std::string::npos,"backup cannot take an inconsistent running snapshot or halt the game");
    f.command("pause");check(f.command("backupPrepare").find("Save backup ready.")!=std::string::npos,"paused engine flushes a consistent backup base");f.command("save","2");auto before=mahoyo::save::read(f.root/"savedata/slot2.whs");
    auto progress=*mahoyo::shared::read(f.root/"savedata/shared.whp");progress.generation++;progress.flags[10]=1;progress.variables[17]=99;progress.variables[18]=55;progress.variables[26]=1<<8;progress.variables[8]=4;progress.variables[9]=2;mahoyo::shared::write(f.root/"savedata/shared.whp",progress);
    registry(f.root/"savedata/seen-images.whp","WOHSEEN1\n\"img_synthetic.mzp\"\n");registry(f.root/"savedata/trophies.whp","WOHTROPHY1 2\n1\n3\n");
    auto state=f.command("progressImport");check(state.find("Imported progress refreshed.")!=std::string::npos&&waiting(state,"input"),"validated imported registries refresh without leaving the current scene");auto unchanged=mahoyo::save::read(f.root/"savedata/slot2.whs");check(unchanged.vm==before.vm&&unchanged.hostExtra==before.hostExtra,"progress refresh itself never writes an existing manual slot");
    f.command("save","2");InspectHost host;mahoyo::vm::Machine vm(host);vm.loadState(mahoyo::save::read(f.root/"savedata/slot2.whs").vm);check(vm.flag(9,true)&&vm.flag(10,true),"import unions shared flags in the live VM");check(vm.variable(26,true)==((1<<5)|(1<<8)),"known numeric unlock mask uses OR rather than max");check(vm.variable(17,true)==5&&vm.variable(18,true)==0&&vm.variable(8,true)==3&&vm.variable(9,true)==100,"existing scalar state, including zero, and chapter/checkpoint pair remain intact");
    f.command("pause");auto persisted=*mahoyo::shared::read(f.root/"savedata/shared.whp");check(persisted.flags[9]&&persisted.flags[10]&&persisted.variables[26]==((1<<5)|(1<<8)),"subsequent engine persistence cannot overwrite imported unlocks");
    registry(f.root/"savedata/trophies.whp","WOHTROPHY1 2\n1\n1\n");state=f.command("progressImport");check(state.find("Save transfer preparation failed.")!=std::string::npos&&state.find("\"error\":\"\"")!=std::string::npos,"invalid imported registry is a nonfatal rejected transaction");f.passed=true;
}
static void titleContinue(){
    Program p;p.push(11);p.push(5);p.op(0xe0);p.dialogue(0);p.push(22);p.push(5);p.op(0xe0);p.dialogue(1);p.op(0xf4);Fixture f(std::move(p));f.command("textSpeed","0");f.firstComplete();f.command("save","2");auto first=mahoyo::save::read(f.root/"savedata/slot2.whs");f.command("advance");f.command("save","2");auto last=mahoyo::save::read(f.root/"savedata/slot2.whs");f.command("title");woh_destroy(f.handle);f.handle=0;fs::remove(f.root/"savedata/slot2.whs");f.handle=woh_create(f.game.string().c_str());f.command("pause");f.command("backupPrepare");
    const auto older=f.root/"savedata/slot1.whs",newer=f.root/"savedata/slot12.whs";f.extraFiles.push_back(older);f.extraFiles.push_back(newer);mahoyo::save::writeAtomic(older,first);fs::last_write_time(older,fs::file_time_type::clock::now()-std::chrono::hours(1));mahoyo::save::writeAtomic(newer,last);
    auto result=f.command("progressImport");check(result.find("Imported progress refreshed.")!=std::string::npos,"title accepts imported manual slots");result=f.command("action","continue");check(result.find("\"notice\":\"Loaded\"")!=std::string::npos,"continue selects an imported slot when its old active slot is absent");f.command("save","2");InspectHost host;mahoyo::vm::Machine vm(host);vm.loadState(mahoyo::save::read(f.root/"savedata/slot2.whs").vm);check(vm.variable(5)==22,"fresh import chooses the latest save even when the imported archive also contains slot1");f.passed=true;
}
static void run(){refresh();titleContinue();}
}
